export function defaultGroundAttributeFields(markerId: string, x = 240, y = 250) {
  return observed.map((row, index) => {
    const fields = { ...row.fields };
    if (typeof fields.X === 'number') {
      fields.X += x - 240;
      if (typeof fields.Y === 'number') fields.Y += y - 250;
    }
    return {
      ...fields,
      PrimitiveId: 'native-default-attr-' + index,
      ParentPrimitiveId: row.role === 'marker' ? markerId : markerId + '-e15',
    };
  });
}
